select energy_manager.load_cards($cards$[
{"id":"p2-b02-042","paper":2,"topic":"Heat Loss Calculation","kind":"problem","front":"An oil with 9% hydrogen (GCV 10,200 kcal/kg) is fired; flue gas is at 180 °C and combustion air at 40 °C. Latent heat of the vapour is 584 kcal/kg and its specific heat is 0.45 kcal/kg °C. Estimate the sensible and latent heat losses, as % of GCV, from the water formed by the hydrogen.","back":"Latent heat loss about 4.6% of GCV; sensible heat loss about 0.5% of GCV; total about 5.1%.","explain":"Hydrogen burns to water, which leaves the stack as vapour. Its latent heat is lost because it is not condensed, and its sensible heat is lost as it cools to the reference temperature.","flash":false,"source":"BEE Book 2 Ch 02 p84","steps":[{"prompt":"Find the water formed per kg of oil.","answer":"9 × H = 9 × 0.09 = 0.81 kg water/kg oil.","explain":"Each kg of hydrogen forms 9 kg of water."},{"prompt":"Find the latent heat loss.","answer":"0.81 × 584 = 473 kcal/kg; as % of GCV: 473 / 10,200 × 100 = 4.64%.","explain":"Latent heat is carried away as vapour in the flue gas."},{"prompt":"Find the sensible heat loss in kcal/kg.","answer":"0.81 × 0.45 × (180 − 40) = 51.0 kcal/kg.","explain":"The question gives the combustion air temperature of 40 °C, so it is used as the reference temperature."},{"prompt":"Express the sensible loss as % of GCV and add the two losses.","answer":"51.0 / 10,200 × 100 = 0.50%; total = 4.64 + 0.50 = 5.14%.","explain":"Both losses are expressed on the same GCV basis as the chapter's L2 formula."}],"order":2171},
{"id":"p2-b02-043","paper":2,"topic":"Boiler Replacement","kind":"problem","front":"A present boiler (80% efficient) makes 5,000 kg/h of steam with enthalpy gain 600 kcal/kg. It burns furnace oil with GCV 10,000 kcal/kg at Rs 15/kg, for 6,000 h/yr. A new boiler of 84% efficiency costs Rs 30 lakh. Find the annual fuel saving and the simple payback.","back":"Fuel saving about 17.9 kg/h, about 107 tonnes per year, worth about Rs 16.1 lakh per year. Simple payback about 1.9 years (ignoring other costs).","explain":"Replacement pays when the efficiency gain on the fuel bill recovers the capital cost within a reasonable time. The book notes boiler plants usually last well over 25 years, so replacement must be studied carefully.","flash":false,"source":"BEE Book 2 Ch 02 p84","steps":[{"prompt":"Find the heat output per hour.","answer":"5,000 × 600 = 3,000,000 kcal/h.","explain":"Heat output is steam flow times enthalpy gain."},{"prompt":"Find the present fuel consumption.","answer":"3,000,000 / (0.80 × 10,000) = 375 kg/h.","explain":"Fuel = heat output / (efficiency × GCV)."},{"prompt":"Find the new fuel consumption.","answer":"3,000,000 / (0.84 × 10,000) = 357.1 kg/h.","explain":"Same steam output, higher efficiency."},{"prompt":"Find the annual fuel saving.","answer":"(375 − 357.1) = 17.9 kg/h; 17.9 × 6,000 = 107,143 kg/yr, about 107 t/yr.","explain":"Multiply the hourly saving by operating hours."},{"prompt":"Find the money saving and the simple payback.","answer":"107,143 kg × Rs 15/kg = Rs 16.07 lakh/yr; payback = 30 / 16.07 = 1.87 years, about 1.9 years.","explain":"Simple payback = capital cost / annual saving. It ignores interest, maintenance and fuel price changes."}],"order":2172},
{"id":"p2-b03-001","paper":2,"topic":"Steam System","kind":"fact","front":"Name four characteristics that make steam a popular heat carrier in industry.","back":"Highest specific heat and latent heat; highest heat transfer coefficient; easy to control and distribute; cheap and inert.","explain":"The chapter lists these as the reasons steam is used for power generation and in sugar, paper, fertiliser, refinery, chemical, food, synthetic fibre and textile plants. Latent heat in particular lets steam deliver large amounts of energy at a constant temperature.","flash":false,"source":"BEE Book 2 Ch 03 p89","order":2173},
{"id":"p2-b03-002","paper":2,"topic":"Steam System","kind":"problem","front":"How much total heat is needed to take 1 kg of water at 25 °C into steam at 100 °C (atmospheric pressure)?","back":"615 kcal/kg: 75 kcal of sensible heat plus 540 kcal of latent heat.","explain":"The chapter's example uses 75 kcal to heat the water to boiling point and 540 kcal to turn it into steam. The latent part is added at constant temperature, so the total is the sum of the two. This is the heat a boiler must supply per kg of steam, before losses.","flash":false,"source":"BEE Book 2 Ch 03 p89","steps":[{"prompt":"Find the sensible heat needed to raise 1 kg of water from 25 °C to 100 °C.","answer":"75 kcal (the chapter's example)","explain":"Sensible heat changes the temperature only."},{"prompt":"Find the latent heat needed to turn the boiling water into steam.","answer":"540 kcal","explain":"No temperature change happens here; this is the enthalpy of evaporation."},{"prompt":"Add the two quantities.","answer":"75 + 540 = 615 kcal/kg","explain":"Total heat from water at 25 °C to steam at 100 °C."}],"order":2174},
{"id":"p2-b03-003","paper":2,"topic":"Steam System","kind":"problem","front":"Find the total heat (enthalpy) of dry saturated steam at 8 kg/cm², given hf = 171.35 kcal/kg and hfg = 489.46 kcal/kg.","back":"660.81 kcal/kg, from h = hf + hfg = 171.35 + 489.46.","explain":"The chapter's worked example for a boiler at 8 kg/cm² uses a saturation temperature of 170 °C. Dry saturated steam has its total heat equal to the liquid enthalpy plus the enthalpy of evaporation.","flash":false,"source":"BEE Book 2 Ch 03 p90","steps":[{"prompt":"Find the saturation temperature at 8 kg/cm².","answer":"170 °C (from the chapter)","explain":"Saturated steam at a fixed pressure boils at a fixed temperature."},{"prompt":"Write the formula for dry saturated steam.","answer":"h = hf + hfg","explain":"Total heat is the liquid enthalpy plus the enthalpy of evaporation."},{"prompt":"Substitute the values.","answer":"171.35 + 489.46","explain":"hf and hfg are read from the steam tables at 8 kg/cm²."},{"prompt":"Add.","answer":"= 660.81 kcal/kg","explain":"This is the total heat of dry saturated steam at 8 kg/cm²."}],"order":2175},
{"id":"p2-b03-004","paper":2,"topic":"Steam System","kind":"problem","front":"The same 8 kg/cm² steam contains 4% moisture. What is its total heat?","back":"641.23 kcal/kg, using dryness fraction X = 0.96.","explain":"Moisture reduces the total heat because only the vapour fraction carries the latent heat. Compared with dry steam (660.81 kcal/kg), the moisture costs about 19.6 kcal/kg.","flash":false,"source":"BEE Book 2 Ch 03 p90","steps":[{"prompt":"Find the dryness fraction X for 4% moisture.","answer":"X = 1 − 0.04 = 0.96","explain":"4% moisture by mass means 96% vapour."},{"prompt":"Write the wet steam formula.","answer":"h = hf + X × hfg","explain":"Only the vapour fraction contributes the latent heat."},{"prompt":"Multiply the latent heat by X.","answer":"0.96 × 489.46 = 469.88 kcal/kg","explain":"This is the latent heat actually carried by the wet steam."},{"prompt":"Add the liquid enthalpy.","answer":"171.35 + 469.88 = 641.23 kcal/kg","explain":"Total heat of the wet steam."}],"order":2176},
{"id":"p2-b03-005","paper":2,"topic":"Steam System","kind":"fact","front":"What is superheat?","back":"Heat added to dry saturated steam without any rise in pressure. The degrees above saturation temperature at that pressure are the degrees of superheat.","explain":"Superheated steam is hotter than saturated steam at the same pressure. The chapter notes it gives up heat more slowly than condensing saturated steam, so it is not desirable for process heating.","flash":false,"source":"BEE Book 2 Ch 03 p90","order":2177},
{"id":"p2-b03-006","paper":2,"topic":"Steam System","kind":"fact","front":"What is the dryness fraction (X) of wet steam, and how is its total heat calculated?","back":"X is the mass fraction of vapour in the steam-water mixture. Total heat = hf + X × hfg.","explain":"Dry saturated steam has X = 1 (100% dry). A mixture exactly halfway between the saturated liquid and saturated vapour lines has X = 0.5, so moisture in steam reduces its usable heat.","flash":false,"source":"BEE Book 2 Ch 03 p90","order":2178},
{"id":"p2-b03-007","paper":2,"topic":"Steam System","kind":"fact","front":"At what temperature and pressure is the critical point of steam, and what is the enthalpy of evaporation there?","back":"374.15 °C and 221.2 bar (a). The enthalpy of evaporation is zero at this point.","explain":"Above this pressure steam is supercritical and has no well-defined boiling point. At the critical point water changes directly into saturated steam.","flash":false,"source":"BEE Book 2 Ch 03 p91","order":2179},
{"id":"p2-b03-008","paper":2,"topic":"Steam System","kind":"fact","front":"What are the recommended steam velocities in pipes for superheated, saturated, and wet or exhaust steam?","back":"Superheated 50–70 m/s; saturated 30–40 m/s; wet or exhaust 20–30 m/s.","explain":"These are the chapter's guide velocities for sizing steam pipes. Pipe size is set from the flow rate and the permissible velocity, then checked against the pressure drop available in the line.","flash":true,"source":"BEE Book 2 Ch 03 p93","order":2180},
{"id":"p2-b03-009","paper":2,"topic":"Steam System","kind":"fact","front":"How does head loss to friction in a pipe depend on flow velocity, and what is the formula?","back":"Head loss is proportional to the velocity squared (u²). hf = 4fLu²/(2gD), where f is the friction factor, L the length, D the diameter and g = 9.81 m/s².","explain":"Doubling the velocity makes the friction loss four times larger. The friction factor f depends on the Reynolds number and is usually read from charts.","flash":false,"source":"BEE Book 2 Ch 03 p94","order":2181},
{"id":"p2-b03-010","paper":2,"topic":"Steam System","kind":"problem","front":"Find the pressure drop over 1 km of 150 mm horizontal pipe carrying 45 m³/h of water at 15 °C, with friction factor f = 0.005.","back":"About 3.43 m of head, which is about 0.34 bar.","explain":"The chapter's pressure-drop example uses the friction head formula after converting the flow to a velocity of about 0.71 m/s. A head of 1 m of water is roughly 0.1 bar.","flash":false,"source":"BEE Book 2 Ch 03 p95","steps":[{"prompt":"Convert the flow rate to m³/s.","answer":"45 / 3600 = 0.0125 m³/s","explain":"Flow in m³/h must be divided by 3600 to get seconds."},{"prompt":"Find the pipe cross-sectional area.","answer":"π × 0.15² / 4 = 0.01767 m²","explain":"The bore is 150 mm, so the radius is 0.075 m."},{"prompt":"Find the flow velocity.","answer":"u = 0.0125 / 0.01767 = 0.71 m/s","explain":"Velocity equals volumetric flow divided by area."},{"prompt":"Apply hf = 4fLu² / (2gD).","answer":"4 × 0.005 × 1000 × 0.71² / (2 × 9.81 × 0.15) = 3.43 m","explain":"Head loss to friction over the 1 km length."},{"prompt":"Convert the head to pressure.","answer":"3.43 m ≈ 0.34 bar","explain":"Use 1 m of water ≈ 0.1 bar to get the pressure difference between the two points."}],"order":2182},
{"id":"p2-b03-011","paper":2,"topic":"Steam System","kind":"problem","front":"A process needs 5,000 kg/h of dry saturated steam at 7 kg/cm² (g), with velocity not to exceed 25 m/s. What is the minimum pipe size?","back":"About 130 mm minimum. Select the next standard size, 150 mm.","explain":"The chapter gets 0.333 m³/s from the mass flow and the steam's specific volume of 0.24 m³/kg at 7 kg/cm² (g). Rounding up to the nearest commercial size keeps the velocity below 25 m/s.","flash":false,"source":"BEE Book 2 Ch 03 p95","steps":[{"prompt":"Convert the mass flow to kg/s.","answer":"5,000 / 3600 = 1.389 kg/s","explain":"Mass flow in kg/h is divided by 3600."},{"prompt":"Find the volumetric flow using the specific volume.","answer":"1.389 × 0.24 = 0.333 m³/s","explain":"Specific volume at 7 kg/cm² (g) is 0.24 m³/kg from the chapter."},{"prompt":"Find the diameter from D = √(4Q / πu).","answer":"√(4 × 0.333 / (π × 25)) = 0.130 m","explain":"Q is the volumetric flow and u is the permitted velocity."},{"prompt":"Select the pipe size.","answer":"130 mm minimum; choose 150 mm, the nearest commercial size","explain":"The next size up keeps the steam velocity under 25 m/s."}],"order":2183},
{"id":"p2-b03-012","paper":2,"topic":"Steam System","kind":"fact","front":"How does pressure drop in a steam pipe change with pipe diameter?","back":"It is inversely proportional to the 5th power of the diameter.","explain":"A small increase in bore gives a large cut in pressure drop and energy cost, but raises installation cost. The optimum pipe size balances these two costs.","flash":false,"source":"BEE Book 2 Ch 03 p96","order":2184},
{"id":"p2-b03-013","paper":2,"topic":"Steam System","kind":"fact","front":"What falling slope should a steam main have in the direction of steam flow?","back":"At least 125 mm of fall for every 30 m of length.","explain":"The water hammer section of the same chapter gives a stricter guide of at least 1 m in every 100 m. The two figures differ in the book, so check which one a specific exam question uses.","flash":true,"source":"BEE Book 2 Ch 03 p96","order":2185},
{"id":"p2-b03-014","paper":2,"topic":"Steam System","kind":"fact","front":"How far apart should drain points be placed along a steam main?","back":"Every 30–45 m along the main, plus at low points and where the main rises.","explain":"Drain points at low points and rises, fitted through an equal tee, catch condensate before it causes wet steam or water hammer. The water hammer section gives 30–50 m as the interval.","flash":false,"source":"BEE Book 2 Ch 03 p96","order":2186},
{"id":"p2-b03-015","paper":2,"topic":"Steam System","kind":"fact","front":"Where should a branch line be connected to a steam main, and why?","back":"At the top of the main.","explain":"A branch taken off the bottom would itself act as a drain and pull condensate from the main. Expansion loops are also needed to take up expansion when steam lines start from cold.","flash":false,"source":"BEE Book 2 Ch 03 p96","order":2187},
{"id":"p2-b03-016","paper":2,"topic":"Steam System","kind":"fact","front":"What are the consequences of not venting air and other non-condensable gases from a steam system?","back":"A lengthy warm-up period, lower plant efficiency and poorer process performance. Air also makes the steam cooler than the gauge suggests.","explain":"Air exerts its own pressure, so the gauge reads the total of steam and air pressure while the steam itself is at a lower temperature. Air also reduces heat transfer and can corrode equipment.","flash":false,"source":"BEE Book 2 Ch 03 p97","order":2188},
{"id":"p2-b03-017","paper":2,"topic":"Steam System","kind":"problem","front":"Steam at 5 kg/cm² (g) carries 20% air. What pressure does the steam part contribute, and what is the mixture temperature compared with pure steam?","back":"Steam contributes 4 kg/cm² (g) and air 1 kg/cm² (g). The mixture is about 152 °C, against 158 °C for pure steam at 5 kg/cm² (g).","explain":"Air adds to the gauge pressure but carries no latent heat, so the temperature of the mixture matches saturated steam at only 4 kg/cm² (g). This is why air in a steam system lowers the actual steam temperature.","flash":false,"source":"BEE Book 2 Ch 03 p98","steps":[{"prompt":"Find the steam share of the pressure.","answer":"0.80 × 5 = 4 kg/cm² (g)","explain":"80% of the mixture is steam."},{"prompt":"Find the air share of the pressure.","answer":"0.20 × 5 = 1 kg/cm² (g)","explain":"20% of the mixture is air."},{"prompt":"Find the temperature of pure steam at 5 kg/cm² (g).","answer":"158 °C (from the chapter)","explain":"This is the temperature the gauge would suggest."},{"prompt":"Find the temperature of the steam-air mixture.","answer":"152 °C, equal to saturated steam at 4 kg/cm² (g)","explain":"The steam temperature follows only the steam's own partial pressure."}],"order":2189},
{"id":"p2-b03-018","paper":2,"topic":"Steam System","kind":"fact","front":"Name five purposes of insulating steam pipes and equipment.","back":"Conserve energy by reducing heat loss; facilitate process temperature control; prevent condensation of steam; prevent damage from fire or corrosive atmospheres; control surface temperature for personal protection and comfort.","explain":"Insulation cuts radiation loss from steam lines and equipment. The chapter says the economic insulation thickness is calculated in its Chapter 5 on insulation and refractories.","flash":false,"source":"BEE Book 2 Ch 03 p98","order":2190},
{"id":"p2-b03-019","paper":2,"topic":"Steam System","kind":"fact","front":"How much pipe heat loss does one uncovered steam flange equal, and what is the remedy?","back":"The loss of about 0.6 m of unlagged pipeline. Fit easily detachable insulation covers to flanges.","explain":"The chapter says five uncovered flanges on a 0.15 m steam pipe waste about 5 tonnes of coal or 3,000 litres of oil a year. Detachable covers allow the flange to be checked without losing heat.","flash":true,"source":"BEE Book 2 Ch 03 p98","order":2191},
{"id":"p2-b03-020","paper":2,"topic":"Steam System","kind":"fact","front":"What are the typical heat transfer coefficients for hot water and for steam as heat sources in a heat exchanger?","back":"Hot water: 1,000–6,000 W/m²K. Steam: 6,000–15,000 W/m²K.","explain":"The chapter says steam heating gives overall coefficients 1.5 to 2 times those of hot water heating. A higher coefficient means heat transfers faster for the same area and temperature difference.","flash":true,"source":"BEE Book 2 Ch 03 p100","order":2192},
{"id":"p2-b03-021","paper":2,"topic":"Steam System","kind":"problem","front":"A steam-jacketed kettle processes 680 kg of milk per batch, heated from 26 °C to 100 °C, with 25% of the mass evaporated at atmospheric pressure. Specific heat of milk is 0.90 kcal/kg °C and latent heat of 1 kg/cm² steam is 525 kcal/kg. How much steam is needed per batch, excluding kettle heating?","back":"About 261 kg of steam per batch.","explain":"The chapter's solution splits the heat into warming the milk (45,288 kcal) and evaporating 170 kg of water (91,800 kcal). The total heat is then divided by the latent heat of the steam, 525 kcal/kg.","flash":false,"source":"BEE Book 2 Ch 03 p101","steps":[{"prompt":"Find the water evaporated per batch.","answer":"0.25 × 680 = 170 kg","explain":"25% of the milk mass is driven off as vapour."},{"prompt":"Find the heat to raise the milk from 26 °C to 100 °C.","answer":"680 × 0.90 × (100 − 26) = 45,288 kcal","explain":"Sensible heat of the milk."},{"prompt":"Find the heat to evaporate 170 kg of water.","answer":"170 × 540 = 91,800 kcal","explain":"540 kcal/kg is the enthalpy of evaporation used in the chapter's example."},{"prompt":"Find the total heat and the steam mass.","answer":"45,288 + 91,800 = 137,088 kcal; 137,088 / 525 = 261 kg per batch","explain":"The steam gives its latent heat of 525 kcal/kg at 1 kg/cm² (g)."}],"order":2193},
{"id":"p2-b03-022","paper":2,"topic":"Steam System","kind":"fact","front":"Why does steam condensing in a heat exchanger give rapid heating?","back":"Its latent heat is released the instant it condenses. That is 2 to 5 times the sensible heat in the hot water formed.","explain":"Hot water and oil heat by convection with no phase change, so they must cool themselves to transfer heat. The chapter notes that pump-driven forced convection is used to improve this.","flash":false,"source":"BEE Book 2 Ch 03 p101","order":2194},
{"id":"p2-b03-023","paper":2,"topic":"Steam System","kind":"problem","front":"A food product containing 80% water is dried at 100 °C down to 10% moisture. Starting from 21 °C, how much heat is needed per kg of original food, and per kg of water removed? Latent heat is 2,257 kJ/kg and specific heat of the food is 3.8 kJ/kg °C.","back":"About 2,056 kJ per kg of original food, and about 2,643 kJ per kg of water removed.","explain":"The chapter's solution first works out that 0.778 kg of water must leave per kg of food. The OCR of the chapter cuts off the latent heat value, so 2,257 kJ/kg is taken from the chapter's own working.","flash":false,"source":"BEE Book 2 Ch 03 p103","steps":[{"prompt":"Work out the dry-matter basis.","answer":"1 kg food = 200 g dry matter + 800 g water","explain":"Starting moisture is 80%."},{"prompt":"Work out the water left at 10% moisture.","answer":"100 × 200 / 900 = 22.2 g of water remains","explain":"At 10% moisture, 900 g dry matter is paired with 100 g water, so 200 g dry matter holds 22.2 g."},{"prompt":"Find the water to remove.","answer":"800 − 22 = 778 g = 0.778 kg","explain":"This is the moisture that must be evaporated."},{"prompt":"Find the sensible heat and the latent heat.","answer":"(100 − 21) × 3.8 = 300.2 kJ; 0.778 × 2,257 = 1,755.9 kJ","explain":"The first term heats the food to 100 °C; the second evaporates the water."},{"prompt":"Find the totals per kg of food and per kg of water removed.","answer":"300.2 + 1,755.9 = 2,056 kJ; 2,056 / 0.778 = 2,643 kJ per kg water removed","explain":"Energy per kg of water removed is the figure used to compare dryers."}],"order":2195},
{"id":"p2-b03-024","paper":2,"topic":"Steam System","kind":"fact","front":"Name the advantages of the inverted bucket steam trap.","back":"Can be made to withstand high pressures; good tolerance to water hammer; can be used on superheated lines with an inlet check valve; failure mode is usually open, which suits turbine drains.","explain":"Its main drawback is the small bleed hole in the bucket, which vents air very slowly. A parallel air vent is often fitted to speed up start-up.","flash":false,"source":"BEE Book 2 Ch 03 p106","order":2196},
{"id":"p2-b03-025","paper":2,"topic":"Steam System","kind":"fact","front":"Which steam trap is described as the closest to an ideal steam trap, and why?","back":"The float-thermostatic trap, because it discharges condensate as soon as it forms, regardless of changes in steam pressure.","explain":"It handles heavy or light loads equally well and resists water hammer. Only the version with a steam lock release valve suits applications where steam locking can occur.","flash":false,"source":"BEE Book 2 Ch 03 p108","order":2197},
{"id":"p2-b03-026","paper":2,"topic":"Steam System","kind":"fact","front":"How does a thermal-element thermostatic steam trap operate?","back":"On start-up the element is contracted and the valve is open. Steam expands the element to close the trap, and cooler condensate contracts it to open the valve again.","explain":"Thermostatic traps are small, lightweight and work across a broad range of pressures and capacities. In steam tracing they may be set to back condensate up the line to extract its heat.","flash":false,"source":"BEE Book 2 Ch 03 p109","order":2198},
{"id":"p2-b03-027","paper":2,"topic":"Steam System","kind":"fact","front":"Above what condensate load are thermostatic steam traps normally not recommended?","back":"Over 7,000 kg/h.","explain":"For light-to-moderately high condensate loads, thermostatic traps offer lower initial cost, long-term energy saving, reduced inventory and ease of application and maintenance.","flash":false,"source":"BEE Book 2 Ch 03 p111","order":2199},
{"id":"p2-b03-028","paper":2,"topic":"Steam System","kind":"fact","front":"Why is a small drain hole in the bottom of a large steam main not enough to drain it?","back":"Steam velocity carries most of the condensate away. A pocket of at least 100 mm diameter at the lowest point is needed.","explain":"The chapter's example is a 15 mm hole in a 150 mm main, which is useless for draining. Condensate must be able to drop into the pocket, where the trap can then drain it.","flash":false,"source":"BEE Book 2 Ch 03 p111","order":2200},
{"id":"p2-b03-029","paper":2,"topic":"Steam System","kind":"fact","front":"Why is group trapping, where several units drain through one trap, rarely successful?","back":"Units at different steam pressures cause water-logging: the heavily loaded unit at lower pressure cannot push its condensate through the common trap.","explain":"Each steam space should have its own trap, with the outlets connected to a common condensate return main.","flash":false,"source":"BEE Book 2 Ch 03 p112","order":2201},
{"id":"p2-b03-030","paper":2,"topic":"Steam System","kind":"fact","front":"What backpressure does 1 m of condensate lift create, and what does a liquid expansion trap do?","back":"1 m of lift gives about 0.1 bar backpressure. A liquid expansion trap discharges cold condensate to waste at start-up.","explain":"A 5 m lift gives 0.5 bar, which reduces the pressure difference pushing condensate through the trap. The expansion trap closes once the main warms up, and the working trap then drains to the return.","flash":false,"source":"BEE Book 2 Ch 03 p114","order":2202},
{"id":"p2-b03-031","paper":2,"topic":"Steam System","kind":"fact","front":"What two questions does steam trap performance assessment answer?","back":"Is the trap working correctly? If not, has it failed open or failed closed?","explain":"A trap that fails open wastes live steam and, if condensate is not returned, water. A trap that fails closed causes no energy loss but cuts heating capacity and can damage equipment.","flash":false,"source":"BEE Book 2 Ch 03 p116","order":2203},
{"id":"p2-b03-032","paper":2,"topic":"Steam System","kind":"fact","front":"Name the three groups of steam trap test methods.","back":"Visual (sight glass, test tee, three-way valve); sound (ultrasonic detector, stethoscope, metal rod); temperature (infrared gun, surface pyrometer, temperature tape or crayon).","explain":"Visual and sound tests work best on traps that cycle on and off or dribble at light load. For high flows, divert condensate ahead of the trap or shut off a secondary flow to see whether the trap still discharges.","flash":true,"source":"BEE Book 2 Ch 03 p117","order":2204},
{"id":"p2-b03-033","paper":2,"topic":"Steam System","kind":"problem","front":"A steam leak has a plume 700 mm long. Using Figure 3.22 (steam loss against plume length), what is the steam loss?","back":"About 10 kg/h.","explain":"The chart's horizontal axis is plume length in mm divided by 100, so 700 mm reads as 7. The chapter's example gives the result as 10 kg/h.","flash":false,"source":"BEE Book 2 Ch 03 p119","steps":[{"prompt":"Convert the plume length to the chart scale.","answer":"700 mm = 7 on the axis marked plume length (mm × 100)","explain":"The chart axis is in units of 100 mm."},{"prompt":"Locate the point on the steam loss curve.","answer":"Move up from 7 on the plume axis to the curve","explain":"The curve links plume length to steam loss in kg/h."},{"prompt":"Read the steam loss.","answer":"About 10 kg/h","explain":"This matches the chapter's worked example."}],"order":2205},
{"id":"p2-b03-034","paper":2,"topic":"Steam System","kind":"fact","front":"How much fuel oil can a 3 mm hole in a pipeline carrying 7 kg/cm² steam waste each year?","back":"About 33 kilolitres of fuel oil per year.","explain":"The chapter says plugging all leakages can save up to about 5% of steam consumption in small and medium plants, and more in plants with several process departments. Leaks on high-pressure mains are costlier than those on low-pressure mains.","flash":false,"source":"BEE Book 2 Ch 03 p119","order":2206},
{"id":"p2-b03-035","paper":2,"topic":"Steam System","kind":"fact","front":"A 1 mm layer of air offers the same resistance to heat as how much water, iron, or copper?","back":"25 μm of water, 2 mm of iron, or 15 mm of copper.","explain":"Air is a very poor conductor, so even a thin air film on the steam side of a heat exchanger cuts heat transfer sharply. Removing air from the supply steam is one of the most effective ways to restore heating performance.","flash":true,"source":"BEE Book 2 Ch 03 p123","order":2207},
{"id":"p2-b03-036","paper":2,"topic":"Steam System","kind":"fact","front":"How does a steam-driven pressure-powered pump return condensate, and why is it used with hot condensate?","back":"Steam pressure pushes condensate from a receiver to the boiler house once a set level is reached. It works cyclically, avoids cavitation and loses little heat as flash steam.","explain":"Hot condensate near 100 °C causes cavitation in centrifugal pumps when the NPSH available is less than the NPSH required. The chapter gives two fixes: raise the NPSH available, or use a pressure-powered pump instead.","flash":false,"source":"BEE Book 2 Ch 03 p125","order":2208},
{"id":"p2-b03-037","paper":2,"topic":"Steam System","kind":"problem","front":"Hot condensate at 7 bar (g) has a heat content of about 721 kJ/kg and is released to atmospheric pressure. What percentage of it flashes to steam?","back":"About 13.4%: excess heat of 302 kJ/kg divided by the 2,258 kJ/kg latent heat at atmospheric pressure.","explain":"Only the heat above what water can hold at the lower pressure (419 kJ/kg at atmospheric) is available to evaporate condensate. The flash fraction is that excess divided by the latent heat at the lower pressure.","flash":false,"source":"BEE Book 2 Ch 03 p126","steps":[{"prompt":"Find the heat the condensate can keep at atmospheric pressure.","answer":"419 kJ/kg (from the chapter)","explain":"This is the sensible heat of water at 0 bar (g)."},{"prompt":"Find the excess heat.","answer":"721 − 419 = 302 kJ/kg","explain":"This excess is available to evaporate some condensate."},{"prompt":"Find the latent heat at atmospheric pressure.","answer":"2,258 kJ/kg","explain":"Heat needed to evaporate 1 kg of water at atmospheric pressure."},{"prompt":"Find the flash percentage.","answer":"302 / 2,258 × 100 = 13.4%","explain":"The percentage of condensate that flashes to steam."}],"order":2209}
]$cards$::jsonb);
